        if (RustTranspiler.RUST_SCALAR_NUM_HELPERS[name] !== undefined) return args.length === RustTranspiler.RUST_SCALAR_NUM_HELPERS[name] ? 'onum' : undefined;
        const boolBase = RustTranspiler.RUST_SCALAR_BOOL_HELPERS[name];
