            let up: Node = n.parent;
            while (up !== undefined && isParenthesizedExpression(up)) up = up.parent;
            if (isBinaryExpression(up) && RustTranspiler.RUST_87RA_COMPARE_OPS.has(up.operatorToken.kind)) compares++;
