            if (this.rustDeclaredNode(n) !== declaration || this.rustEnclosingFunction(n) !== fn) return false;
            const call: any = n.parent;
            if (rewritten && isBinaryExpression(call) && call.left === n) return this.rustHandedMapWrite(n, declaration);
